        var changes=new LinkedHashMap<String,Object>();changes.put("id",ITEM);changes.put("run_id",run);changes.put("source_id","fictional-second");changes.put("source_item_id",member.sourceItemId());changes.put("member_id",member.memberId());changes.put("observation_id",member.observationId());changes.put("revision",3L);changes.put("state","pending");changes.put("projection_decision","initialized");for(String name:List.of("entity_id","counted_occurrence_key","is_new","dedup_json","analysis_job_id","applied_at"))changes.put(name,null);f.cloneRow("source_run_items","fictional-current-item",changes);
        f.f.jdbc.update("INSERT INTO request_receipts(id,run_id,scope,receipt_kind,control_operation,ack_json,business_hash) VALUES('fictional-registered-second-part',? ,?,'collector_control','manifest',?,?)",run,"manifest:"+run+":0",JdbcFrozenInputs.canonical(payload),HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.CONTROL_BUSINESS,control)));
