        var readiness=new DispatchReadinessService(new JdbcDispatchInputs(f.f.source),inputs,new FrozenDependencyIndexService(inputs,new JdbcFrozenDependencies(f.f.source)),new GenerationLineageService(new JdbcGenerationLineage(f.f.source),f.f.clock,"analysis-worker"),new ContentReadService(new JdbcContentReads(f.f.source),f.f.tx,ContentReadService.denyUnverifiedReferences()),new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(f.f.source)),target->{throw new AssertionError("source dedup has no synthetic citation targets");},f.graph.collections()::read,new SourcePartitionProofService(f.graph.plans()),true);
        var worker=new WorkerAuthorizationService(f.f.writes,new WorkerJdbcStore(new JdbcWorkerState(f.f.source),new JdbcJobRecords(f.f.source),"fictional-registered-second-epoch",()->false,readiness::ready,f.f.clock),f.f.clock,()->true);var claim=worker.claim(new SharedWriteExecutor.ActionContext("fictional-registered-second-claim",root.ownerId(),root.inputHash()));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());assertEquals(WorkerAuthorizationService.State.SENT,worker.dispatch(claim.permit(),request->{assertEquals(root.requestJson(),JdbcFrozenInputs.canonical(CanonicalJson.parse(request)));f.f.sends++;return "fictional second registered source result";}).state());
