        assertEquals(ResultApplicationService.Status.APPLIED,application.service().applyAutomatic(application.input(),ResultApplicationService.providerEnvelope(application.input(),JdbcFrozenInputs.canonical(answer)),new SharedWriteExecutor.ActionContext("fictional-registered-second-apply",root.ownerId(),root.inputHash())).status());
