    Map<String,CatalogDayAnalysisProofGraph> graphs(Built built,Clock clock){var f=built.fixture();var settings=(GenerationFlowService.SettingsSnapshotSource)()->new FrozenGenerationSettings(7,List.of("Fictional watch"),List.of());var all=new LinkedHashMap<String,CatalogDayAnalysisProofGraph>();for(String category:CatalogSourceProofConfiguration.CATEGORIES){var sources=category.equals(f.f.category)?f.graph:new CatalogSourceProofGraph(f.f.source,f.f.tx,clock,settings,()->true,category);all.put(category,new CatalogDayAnalysisProofGraph(f.f.source,f.f.tx,clock,f.cohorts,f.runs,sources,settings,()->true,category));}return all;}
    @Test void FourActualCategoriesMergeBothRegisteredSourcesIntoOneGenerationAndCompleteOriginalAnalysis(){
        for(String category:List.of("agent","skill","workflow","model")){var built=fixture(category);var f=built.fixture();var clock=Clock.fixed(built.outer().completed.plusSeconds(120),ZoneOffset.UTC);var registry=new CatalogDayAnalysisProofConfiguration.Graphs(graphs(built,clock));var graph=registry.graph(category);var original=graph.evidence().capture(built.outer().day);assertEquals(2,original.original().sources().size());assertEquals(1,original.entities().size());assertEquals(2,original.entities().getFirst().members().size());assertEquals(Set.of(f.sourceRunId(),built.secondRun()),original.entities().getFirst().members().stream().map(e->e.member().runId()).collect(java.util.stream.Collectors.toSet()));assertTrue(graph.barrier().find(built.outer().day).closure().early());assertTrue(graph.barrier().find(built.outer().day).closure().entries().stream().allMatch(e->e.decision()==SourceDedupBarrier.Decision.INCLUDED));
            assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.PREPARED,graph.cycle().run(()->true));var prepared=graph.prepared().find(built.outer().day,"fictional-entity");assertNotNull(prepared);assertEquals(2,prepared.reservation().generation());assertEquals(2,prepared.reservation().members().size());var snapshot=CanonicalJson.parse(prepared.input().snapshotJson());assertEquals(2,snapshot.get("members").size());assertEquals(2,snapshot.get(CatalogAnalysisInputProfile.FIELD).get("source_proofs").size());assertEquals("complete",prepared.input().coverageState());assertTrue(prepared.input().missing().isEmpty());
            CatalogDayAnalysisDispatchTest.columns(f.f.source,f.f.jdbc,"source_run_items","validity_revision BIGINT DEFAULT 0");CatalogDayAnalysisDispatchTest.columns(f.f.source,f.f.jdbc,"jobs","validity_revision BIGINT","reverses_disposition_id VARCHAR(64)");var generated=new GeneratedContentService(new JdbcGeneratedContents(f.f.source),clock);var ledger=new VersionValidityLedgerService(new JdbcVersionValidity(f.f.source),new FrozenContentVersionService(new JdbcFrozenContentVersions(f.f.source)),new EvidenceValidityService(new JdbcEvidenceValidity(f.f.source)),new ContentReviewWriteService(new JdbcReviewPublication(f.f.source),generated,clock),clock,"fictional-owner");var inputs=new JdbcFrozenInputs(f.f.source);var readiness=new DispatchReadinessService(new JdbcDispatchInputs(f.f.source),inputs,new FrozenDependencyIndexService(inputs,new JdbcFrozenDependencies(f.f.source)),new GenerationLineageService(new JdbcGenerationLineage(f.f.source),clock,"analysis-worker"),new ContentReadService(new JdbcContentReads(f.f.source),f.f.tx,ContentReadService.denyUnverifiedReferences()),new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(f.f.source)),target->ledger.exactVersionExists(target)&&ledger.validity(target).effectiveValid(),null,null,false,null,null,f.f.tx,null,registry.dispatchPermissions());var worker=new WorkerAuthorizationService(f.f.writes,new WorkerJdbcStore(new JdbcWorkerState(f.f.source),new JdbcJobRecords(f.f.source),"fictional-two-source-analysis-epoch",()->false,readiness,clock,f.f.tx),clock,()->true);var claim=worker.claim(new SharedWriteExecutor.ActionContext("fictional-two-source-analysis-claim",prepared.input().ownerId(),prepared.input().inputHash()));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());assertEquals(WorkerAuthorizationService.State.SENT,worker.dispatch(claim.permit(),request->{assertEquals(prepared.input().requestJson(),JdbcFrozenInputs.canonical(CanonicalJson.parse(request)));f.f.sends++;return "fictional whole two source analysis";}).state());
            var factory=new ResultApplicationFactory(f.f.source,f.f.tx,clock,registry.resultPermissions());var application=factory.forAttempt(claim.permit().identity());var body=JsonMapper.shared().createObjectNode().put("title","Fictional whole two source analysis").put("category",category).put("entity_id","fictional-entity");body.putArray("sections");var refs=body.putArray("citation_ids");application.input().allowedCitationIds().stream().sorted().forEach(refs::add);var answer=JsonMapper.shared().createObjectNode().put("kind","analysis");answer.set("body",body);String raw=ResultApplicationService.providerEnvelope(application.input(),JdbcFrozenInputs.canonical(answer));var action=new SharedWriteExecutor.ActionContext("fictional-two-source-analysis-apply",prepared.input().ownerId(),prepared.input().inputHash());var result=application.service().applyAutomatic(application.input(),raw,action);assertEquals(ResultApplicationService.Status.APPLIED,result.status());assertEquals(2,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals("analyzed",f.f.jdbc.queryForObject("SELECT analysis_state FROM analyzed_entities",String.class));assertEquals(2,CanonicalJson.parse(f.f.jdbc.queryForObject("SELECT body_json FROM contents WHERE id=?",String.class,result.contentId())).get("citation_ids").size());assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_day_analysis'",Integer.class));assertEquals(1,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE root_job_id=? AND record_kind='ai_attempt'",Integer.class,prepared.input().ownerId()));assertEquals(4,f.f.sends);
            int jobs=f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);for(String table:List.of("sources","source_run_items","analyzed_entities","contents"))f.f.jdbc.execute("DROP TABLE "+table);var replay=factory.forAttempt(claim.permit().identity());assertEquals(result,replay.service().applyAutomatic(replay.input(),raw,action));assertEquals(prepared.input(),graph.preparation().prepare(built.outer().day,"fictional-entity").input());assertEquals(jobs,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(4,f.f.sends);
        }
    }
    @Test void DamagedSecondOriginalFinalRefusesWholeDayWithoutAllocatingAnotherGeneration(){var built=fixture("agent");var f=built.fixture();var committed=snapshot(f,()->f.graph.finalizer().readCommitted(built.secondRef()));f.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE id=?",new byte[32],committed.receipt().position().receiptId());var graph=graphs(built,Clock.fixed(built.outer().completed.plusSeconds(120),ZoneOffset.UTC)).get("agent");assertEquals(CatalogDayAnalysisPreparationCycle.Outcome.RECOVERY_REQUIRED,graph.cycle().run(()->true));assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_day_analysis'",Integer.class));assertEquals(2,f.f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(3,f.f.sends);}
